{
  "per_column": [
    {
      "name": "service_attentiveness",
      "analytical_usefulness": 0.9,
      "source_groundedness": 0.9,
      "rationale": "A well-defined categorical axis (attentive/slow/dismissive/not_present) that directly targets what businesses can improve for satisfaction. Samples are sound readings: YLP-0002's neglect maps to slow_neglectful, YLP-0005 to dismissive_rude, YLP-0001 to attentive. 'not_present' handles silent rows correctly."
    },
    {
      "name": "staff_communication_quality",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.6,
      "rationale": "Communication is a distinct actionable lever, so useful. However it overlaps heavily with service_attentiveness and its values are sometimes over-asserted: YLP-0001 and YLP-0003 give 'clear_informative' though the text says little about communication specifically, and 'rude_untruthful' for YLP-0005 imports an 'untruthful' claim the text doesn't support. Some warranted inference is stretched."
    },
    {
      "name": "food_taste_execution",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.85,
      "rationale": "Food quality is a core satisfaction driver and a genuine new axis. Values are grounded: pizza reviews map to excellent_flavorful, and NULL is correctly used for non-food reviews (real-estate YLP-0004, club YLP-0005). Sound extraction behaviour."
    },
    {
      "name": "ambiance_comfort",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.7,
      "rationale": "Ambiance is a legitimate distinct dimension for improvement. Mostly grounded with correct NULLs, but some values are weakly supported: YLP-0001 'pleasant_welcoming' and YLP-0003 'neutral' are inferred where the text barely describes atmosphere; YLP-0005 'poor_unpleasant' is a reasonable read of the exclusionary environment."
    }
  ],
  "analytical_usefulness": 0.83,
  "source_groundedness": 0.76,
  "rationale": "The four columns give genuine, actionable axes (service, communication, food, ambiance) directly aligned to how businesses could improve Yelp satisfaction, enabling grouping and comparison beyond the raw sentiment label. Groundedness is generally solid with correct NULL/not_present handling for silent rows, but staff_communication_quality and ambiance_comfort occasionally over-assert specific readings where the source is thin (e.g., 'clear_informative' and 'untruthful' claims not clearly warranted), and communication overlaps notably with attentiveness. No fabricated facts contradicting the text observed."
}

